-- Public API (generated)
local VM = {}

function VM.load(chunk, env)
  local factory = load_chunk(chunk, env or _G)
  local cl = factory({[0] = {open = false, val = env or _G}})
  local f = function(...) return execute(cl, ...) end
  closure_map[f] = cl
  return f
end

function VM.run(closure, ...)
  return execute(closure, ...)
end

function VM.exec(chunk, ...)
  local closure = VM.load(chunk)
  return execute(closure, ...)
end

function VM.pack(proto)
  return vm_pack_proto(proto)
end

return VM
